Q: In an ES5-style class, how to arrange a custom “.toString” method, normally attached to a prototype, to be able to access private state? A: <p>It's possible to keep the prototype toString method whilst protecting <code>store</code>, by adding a public method that returns the stringified <code>store</code>, and calling it from <code>Store.prototype.toString</code>.</p>

<p>Below I added <code>this.getStoreString</code> to the constructor, and called it from the original <code>toString</code>.</p>

<pre><code>(function () {
    function Store() {
        var store = [];

        if (!(this instanceof Store)) {
            return new Store();
        }

        this.add = function (name, price) {
            store.push(new StoreItem(name, price));
            return this;
        };

        // new method
        this.getStoreString = function(){
            return store.join('\r\n');  
        };
    }

    function StoreItem(name, price) {
        if (!(this instanceof StoreItem)) {
            return new StoreItem();
        }

        this.Name = name || 'Default item';
        this.Price = price || 0.0;
    }

    Store.prototype.toString = function () {
        // call the new method
        return this.getStoreString();
    };

    StoreItem.prototype.toString = function () {
        return this.Name + ' $' + this.Price;
    };

    window.shop = window.shop || {
        Store: function () {
            return new Store();
        }
    };
}());
</code></pre>

<p><strong><a href="https://jsfiddle.net/900hpgkm/" rel="nofollow">Fiddle</a></strong></p>

<p>@Bergi's answer seems simpler though, but this shows another option.</p>
